func newAuthEvent() unsafe.Pointer { return unsafe.Pointer(new(iam.AuthEvent)) }

func newNAuthEvent(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]iam.AuthEvent, n)))
}

func ptrAuthEvent(p unsafe.Pointer, c int32) any {
	r := (*iam.AuthEvent)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 4:
		return (*string)(unsafe.Pointer(&r.IdentityProviderID))
	case 5:
		return &r.Provider
	case 6:
		return (*string)(unsafe.Pointer(&r.Outcome))
	case 7:
		return &r.IPAddress
	case 8:
		return &r.UserAgent
	case 9:
		return (*int64)(unsafe.Pointer(&r.AuthenticatorAAL))
	case 10:
		return (*int64)(unsafe.Pointer(&r.FederationFAL))
	case 11:
		return &r.MFAState
	case 12:
		return (*string)(unsafe.Pointer(&r.RiskOutcome))
	case 13:
		return &r.RiskSignals
	case 14:
		return &r.ErrorCode
	case 15:
		return &r.OccurredAt
	case 16:
		return &r.CreatedAt
	}
	return nil
}

func valueAuthEvent(p unsafe.Pointer, c int32) any {
	r := (*iam.AuthEvent)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		if r.UserID == "" {
			return nil
		}
		return string(r.UserID)
	case 2:
		if r.OrganizationID == "" {
			return nil
		}
		return string(r.OrganizationID)
	case 3:
		if r.BusinessUnitID == "" {
			return nil
		}
		return string(r.BusinessUnitID)
	case 4:
		if r.IdentityProviderID == "" {
			return nil
		}
		return string(r.IdentityProviderID)
	case 5:
		return r.Provider
	case 6:
		return string(r.Outcome)
	case 7:
		if r.IPAddress == "" {
			return nil
		}
		return r.IPAddress
	case 8:
		if r.UserAgent == "" {
			return nil
		}
		return r.UserAgent
	case 9:
		return int64(r.AuthenticatorAAL)
	case 10:
		return int64(r.FederationFAL)
	case 11:
		if r.MFAState == "" {
			return nil
		}
		return r.MFAState
	case 12:
		return string(r.RiskOutcome)
	case 13:
		if r.RiskSignals == nil {
			return []string{}
		}
		return r.RiskSignals
	case 14:
		if r.ErrorCode == "" {
			return nil
		}
		return r.ErrorCode
	case 15:
		return r.OccurredAt
	case 16:
		return r.CreatedAt
	}
	return nil
}

