func newExternalIdentity() unsafe.Pointer { return unsafe.Pointer(new(iam.ExternalIdentity)) }

func newNExternalIdentity(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]iam.ExternalIdentity, n)))
}

func ptrExternalIdentity(p unsafe.Pointer, c int32) any {
	r := (*iam.ExternalIdentity)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 4:
		return (*string)(unsafe.Pointer(&r.IdentityProviderID))
	case 5:
		return &r.ExternalSubject
	case 6:
		return &r.ExternalUsername
	case 7:
		return &r.ExternalEmail
	case 8:
		return &r.RawClaims
	case 9:
		return &r.LastLoginAt
	case 10:
		return &r.CreatedAt
	case 11:
		return &r.UpdatedAt
	}
	return nil
}

func valueExternalIdentity(p unsafe.Pointer, c int32) any {
	r := (*iam.ExternalIdentity)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.UserID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.BusinessUnitID)
	case 4:
		return string(r.IdentityProviderID)
	case 5:
		return r.ExternalSubject
	case 6:
		if r.ExternalUsername == "" {
			return nil
		}
		return r.ExternalUsername
	case 7:
		if r.ExternalEmail == "" {
			return nil
		}
		return r.ExternalEmail
	case 8:
		if r.RawClaims == nil {
			return keel.EmptyJSONObject
		}
		return r.RawClaims
	case 9:
		if r.LastLoginAt == 0 {
			return nil
		}
		return r.LastLoginAt
	case 10:
		return r.CreatedAt
	case 11:
		return r.UpdatedAt
	}
	return nil
}

