func newSCIMToken() unsafe.Pointer { return unsafe.Pointer(new(iam.SCIMToken)) }

func newNSCIMToken(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]iam.SCIMToken, n)))
}

func ptrSCIMToken(p unsafe.Pointer, c int32) any {
	r := (*iam.SCIMToken)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.DirectoryID))
	case 3:
		return &r.Name
	case 4:
		return &r.Prefix
	case 5:
		return &r.TokenHash
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.LastUsedAt
	case 8:
		return &r.ExpiresAt
	case 9:
		return &r.CreatedAt
	case 10:
		return &r.UpdatedAt
	}
	return nil
}

func valueSCIMToken(p unsafe.Pointer, c int32) any {
	r := (*iam.SCIMToken)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.DirectoryID)
	case 3:
		return r.Name
	case 4:
		return r.Prefix
	case 5:
		return r.TokenHash
	case 6:
		return string(r.Status)
	case 7:
		if r.LastUsedAt == 0 {
			return nil
		}
		return r.LastUsedAt
	case 8:
		if r.ExpiresAt == 0 {
			return nil
		}
		return r.ExpiresAt
	case 9:
		return r.CreatedAt
	case 10:
		return r.UpdatedAt
	}
	return nil
}

